import numpy as np
def rk4(f,y,t,dt):
    k1=f(t,y); k2=f(t+dt/2,y+dt*k1/2)
    k3=f(t+dt/2,y+dt*k2/2); k4=f(t+dt,y+dt*k3)
    return y+dt/6*(k1+2*k2+2*k3+k4)
f=lambda t,y:-y; y=1.0; dt=0.1
for n in range(10): y=rk4(f,y,n*dt,dt)
print(round(y,6), round(np.exp(-1),6))  # 0.367879 vs 0.367879

import numpy as np
def euler(f,y0,t0,tf,dt):
    y=y0; t=t0
    while t<tf-1e-12:
        y=y+dt*f(t,y); t+=dt
    return y
f=lambda t,y:-2*y; exact=np.exp(-2)
for dt in [0.2,0.1,0.05]:
    print(dt, round(abs(euler(f,1,0,1,dt)-exact),4))  # error halves as dt halves

import numpy as np
def trap(f,a,b,n):
    x=np.linspace(a,b,n+1); h=(b-a)/n; y=f(x)
    return h*(y[0]/2+y[-1]/2+y[1:-1].sum())
for n in [4,8,16,32]:
    print(n, round(abs(trap(np.sin,0,np.pi,n)-2),6))  # error ~ 1/n^2

import numpy as np
def entropy(y):
    p=np.bincount(y)/len(y); p=p[p>0]
    return -(p*np.log2(p)).sum()
x=np.array([1,2,3,4,5,6.]); y=np.array([0,0,0,1,1,1])
best=None
for thr in (x[:-1]+x[1:])/2:
    L=y[x<thr]; R=y[x>=thr]
    child=(len(L)*entropy(L)+len(R)*entropy(R))/len(y)
    gain=entropy(y)-child
    if best is None or gain>best[1]: best=(thr,gain)
print('best threshold',best[0],'gain',round(best[1],3))

def nand(a,b): return 1-(a&b)
def xor(a,b):
    t=nand(a,b); return nand(nand(a,t),nand(b,t))
def full_adder(a,b,cin):
    ab=xor(a,b); s=xor(ab,cin)
    c1=nand(a,b); c2=nand(ab,cin)
    cout=nand(c1,c2)             # = AB + Cin(A xor B)
    return s,cout
for a in (0,1):
    for b in (0,1):
        for c in (0,1):
            print(a,b,c,'->',full_adder(a,b,c))

import numpy as np
y=np.array([0,0,1,1,1,0,1,0])
score=np.array([.1,.4,.35,.8,.7,.5,.9,.2])
def rates(thr):
    pred=score>=thr
    tp=((pred==1)&(y==1)).sum(); fp=((pred==1)&(y==0)).sum()
    tpr=tp/(y==1).sum(); fpr=fp/(y==0).sum()
    return round(fpr,2),round(tpr,2)
for thr in [0.3,0.5,0.75]:
    print('thr',thr,'-> (FPR,TPR)',rates(thr))
